    "resourceSvg": "<svg viewBox=\"0 0 500 160\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <filter id=\"res-glow-04\" filterUnits=\"userSpaceOnUse\" x=\"0\" y=\"0\" width=\"500\" height=\"160\">\n      <feGaussianBlur stdDeviation=\"2\" result=\"blur\" />\n      <feMerge><feMergeNode in=\"blur\" /><feMergeNode in=\"SourceGraphic\" /></feMerge>\n    </filter>\n  </defs>\n  <text x=\"250\" y=\"15\" font-family=\"'JetBrains Mono'\" font-size=\"8\" fill=\"#94a3b8\" text-anchor=\"middle\">Server Thread Usage — Before vs After Spatial Optimization</text>\n  <text x=\"40\" y=\"40\" font-family=\"'Outfit'\" font-size=\"8\" fill=\"#64748b\">THREADS</text>\n  <rect x=\"110\" y=\"30\" width=\"310\" height=\"14\" fill=\"#f857a6\" filter=\"url(#res-glow-04)\" rx=\"3\" opacity=\"0.7\" />\n  <text x=\"430\" y=\"41\" font-family=\"'JetBrains Mono'\" font-size=\"8\" fill=\"#f857a6\">72%</text>\n  <rect x=\"110\" y=\"50\" width=\"110\" height=\"14\" fill=\"#10b981\" filter=\"url(#res-glow-04)\" rx=\"3\" />\n  <text x=\"230\" y=\"61\" font-family=\"'JetBrains Mono'\" font-size=\"8\" fill=\"#10b981\">27% (indexed)</text>\n  <text x=\"40\" y=\"90\" font-family=\"'Outfit'\" font-size=\"8\" fill=\"#64748b\">MATCH ms</text>\n  <rect x=\"110\" y=\"80\" width=\"350\" height=\"14\" fill=\"#f857a6\" filter=\"url(#res-glow-04)\" rx=\"3\" opacity=\"0.7\" />\n  <text x=\"470\" y=\"91\" font-family=\"'JetBrains Mono'\" font-size=\"8\" fill=\"#f857a6\">480ms</text>\n  <rect x=\"110\" y=\"100\" width=\"80\" height=\"14\" fill=\"#10b981\" filter=\"url(#res-glow-04)\" rx=\"3\" />\n  <text x=\"200\" y=\"111\" font-family=\"'JetBrains Mono'\" font-size=\"8\" fill=\"#10b981\">180ms</text>\n  <rect x=\"140\" y=\"130\" width=\"10\" height=\"10\" fill=\"#f857a6\" rx=\"2\" opacity=\"0.7\" />\n  <text x=\"156\" y=\"139\" font-family=\"'Outfit'\" font-size=\"7\" fill=\"#94a3b8\">Sequential Coordinate Scan</text>\n  <rect x=\"280\" y=\"130\" width=\"10\" height=\"10\" fill=\"#10b981\" rx=\"2\" />\n  <text x=\"296\" y=\"139\" font-family=\"'Outfit'\" font-size=\"7\" fill=\"#94a3b8\">Spatial Index + Geofencing</text>\n</svg>",
    "resourceDesc": "Implementing spatial coordinate indexing and geofencing formulas reduced server thread utilization from 72% to 27% and driver matching times from 480ms to 180ms at 2,000 concurrent ride requests.",
