    "resourceSvg": "<svg viewBox=\"0 0 500 160\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <filter id=\"res-glow-05\" filterUnits=\"userSpaceOnUse\" x=\"0\" y=\"0\" width=\"500\" height=\"160\">\n      <feGaussianBlur stdDeviation=\"2\" result=\"blur\" />\n      <feMerge><feMergeNode in=\"blur\" /><feMergeNode in=\"SourceGraphic\" /></feMerge>\n    </filter>\n  </defs>\n  <text x=\"250\" y=\"15\" font-family=\"'JetBrains Mono'\" font-size=\"8\" fill=\"#94a3b8\" text-anchor=\"middle\">Notification Latency — HTTP Polling vs WebSocket Push</text>\n  <text x=\"40\" y=\"40\" font-family=\"'Outfit'\" font-size=\"8\" fill=\"#64748b\">LATENCY</text>\n  <rect x=\"110\" y=\"30\" width=\"340\" height=\"14\" fill=\"#f857a6\" filter=\"url(#res-glow-05)\" rx=\"3\" opacity=\"0.7\" />\n  <text x=\"460\" y=\"41\" font-family=\"'JetBrains Mono'\" font-size=\"8\" fill=\"#f857a6\">350ms avg</text>\n  <rect x=\"110\" y=\"50\" width=\"20\" height=\"14\" fill=\"#10b981\" filter=\"url(#res-glow-05)\" rx=\"3\" />\n  <text x=\"140\" y=\"61\" font-family=\"'JetBrains Mono'\" font-size=\"8\" fill=\"#10b981\">12ms constant</text>\n  <text x=\"40\" y=\"90\" font-family=\"'Outfit'\" font-size=\"8\" fill=\"#64748b\">CPU POLL</text>\n  <rect x=\"110\" y=\"80\" width=\"250\" height=\"14\" fill=\"#f857a6\" filter=\"url(#res-glow-05)\" rx=\"3\" opacity=\"0.7\" />\n  <text x=\"370\" y=\"91\" font-family=\"'JetBrains Mono'\" font-size=\"8\" fill=\"#f857a6\">58% overhead</text>\n  <rect x=\"110\" y=\"100\" width=\"45\" height=\"14\" fill=\"#10b981\" filter=\"url(#res-glow-05)\" rx=\"3\" />\n  <text x=\"165\" y=\"111\" font-family=\"'JetBrains Mono'\" font-size=\"8\" fill=\"#10b981\">8% persistent</text>\n  <rect x=\"140\" y=\"130\" width=\"10\" height=\"10\" fill=\"#f857a6\" rx=\"2\" opacity=\"0.7\" />\n  <text x=\"156\" y=\"139\" font-family=\"'Outfit'\" font-size=\"7\" fill=\"#94a3b8\">Traditional HTTP Polling</text>\n  <rect x=\"280\" y=\"130\" width=\"10\" height=\"10\" fill=\"#10b981\" rx=\"2\" />\n  <text x=\"296\" y=\"139\" font-family=\"'Outfit'\" font-size=\"7\" fill=\"#94a3b8\">Socket.io Persistent Connection</text>\n</svg>",
    "resourceDesc": "Replacing traditional HTTP polling with persistent Socket.io WebSocket connections reduced notification latency from 350ms average to a constant 12ms and dropped CPU polling overhead from 58% to just 8%.",
    "roi": [
      "97% reduction in notification latency: Socket.io persistent connections deliver constant 12ms fleet updates vs 350ms fluctuating HTTP polling delays, critical for national cargo coordination.",
      "86% reduction in server CPU overhead: Eliminating continuous HTTP polling cycles freed 50% of server processing power for route calculation and geospatial analysis.",
      "Zero memory leaks on long sessions: Decoupled WebSocket event routing with proper JWT handshake cleanup ensures stable persistent connections across 24/7 dispatch operations."
    ],
